import test from'node:test';import assert from'node:assert/strict';import{validateRestorationProof}from'./sharp-restore-transport.mjs';
const fixture=()=>{const grant={installId:'new',source:'source',baseline:'baseline',expiresAt:'expiry'},relationship={authorizationSha256:'auth'},descriptor={package:'sharp',version:'0.35.5',packageJsonSha256:'package',packageTreeSha256:'d69a084d753231b315413e9b8c3d7bf17abb7e4fe7b26bf9c68aa32e2a12ce2f'},proof={kind:'EXACT_CI_SHARP_GENERATED_SHIM_RESTORED',onlyGeneratedShimWritten:true,integrityPolicyChanged:false,applicationBuildRun:false,oldRawSha256:'3a523b560dfe5049570bbcbee1f5357edabe702bc741852f09e1c93c00b3f09b',newRawSha256:'0dfe5d20ee7bef74669a0ba3ad521069d89985856c36b473986c293ffe6a490a',completePackage:descriptor,authority:{newInstallId:'new',source:'source',baseline:'baseline',expiresAt:'expiry',authorizationSha256:'auth'}};return{grant,relationship,descriptor,proof};};
test('exact full package and fresh authority required',()=>{const x=fixture();assert.equal(validateRestorationProof(x.proof,x),x.proof);});
for(const[k,v]of Object.entries({kind:'preview',onlyGeneratedShimWritten:false,integrityPolicyChanged:true,applicationBuildRun:true,oldRawSha256:'changed',newRawSha256:'changed',completePackage:{},authority:{}}))test('refuses changed restoration '+k,()=>{const x=fixture();x.proof[k]=v;assert.throws(()=>validateRestorationProof(x.proof,x));});
